/* machine-generated by m2c: a starting point, not a match */

extern s32 gBonusTextNodes;
extern s32 gBonusTextActiveIndex;

/* Clears the four bonus text node slots and resets the active index to -1. */ void clearBonusTextNodes(void) {
    char *slot;
    u32 i;

    i = 0;
    slot = &gBonusTextNodes;
    do {
        *(s32 *)slot = 0;
        i += 1;
        slot += 4;
    } while (i < 4U);
    gBonusTextActiveIndex = -1;
}
